/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import java.util.Map;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.core.App;import page2020.util.EmptyUtil;import page2020.view.Content;import page2020.view.Text;import page2020.view.Value;import page2020.view.bs4.B4show.D;import page2020.view.html5.H5input;import page2020.view.html5.H5input.Type;import page2020.view.html5.H5label;import page2020.view.html5.H5span;public class B4radio extends B4box<B4radio> {	public static final String radio = "custom-radio";	private static Logger log = LoggerFactory.getLogger(B4radio.class);	public B4radio() {		this(new H5input());	}	public B4radio(H5input input) {		super();		super.data(PageKey.type, "radio");		super.append(input.type(Type.radio).id(B4ctrl.id()).cssClass(B4ctrl.input).value(""));	}	public B4radio items(String datalistKey) {		H5input input = (H5input) super.remove(0);			String id = (String) input.getAttrMap().get(Attr.id);		H5span tip = null;		if (super.count() > 0) {			tip = (H5span) super.remove(0);		}				if (EmptyUtil.not(datalistKey)) {			Map<String, Object> items = App.itemValue(datalistKey);			if (items != null) {								int index = 0;				for (String item : items.keySet()) {					String id2 = id + "." + (++index);					String code = App.itemKey(datalistKey, item);					super.append(new B4element().cssClass(B4ctrl.custom, B4ctrl.inline, radio).append(						input.copy().id(id2).value(item),						new H5label().forE(id2).cssClass(B4ctrl.label).append(new Text().code(code))					));				}			} else {				log.error("items: argument(" + datalistKey + ") are invalid !");			}		} else {			log.error("items: argument(datalistKey) has empty !");		}		if (tip != null) {			super.append(tip.removeClass(D.none));		}		return this;	}	public B4radio items(String className, String fieldName) {		return this.items(className + "." + fieldName);	}	public B4radio items(Class<?> clazz, String fieldName) {		return this.items(App.className(clazz), fieldName);	}	public B4radio items(Map<String, ?> items) {		H5input input = (H5input) super.remove(0);			String id = (String) input.getAttrMap().get(Attr.id);		H5span tip = null;		if (super.count() > 0) {			tip = (H5span) super.remove(0);		}		if (items != null) {			int index = 0;			for (String key : items.keySet()) {				String id2 = id + "." + (++index);				super.append(new B4element().cssClass(B4ctrl.custom, B4ctrl.inline, radio).append(					input.copy().id(id2).value(key),					new H5label().forE(id2).cssClass(B4ctrl.label).append(new Value().value(items.get(key)))				));			}		} else {			log.error("items: argument(items) is empty !");		}		if (tip != null) {			super.append(tip.removeClass(D.none));		}		return this;	}	public B4radio disabled(boolean disabled) {		if (super.count() > 0) {			super.getContents().forEach(c -> {				if (c instanceof B4element) {					B4element element = (B4element) c;					((H5input) element.get(0)).disabled(disabled);					}			});		}				return this;	}	@Override	public B4radio value(Object value) {		if (EmptyUtil.not(value)) {			for (Content<?> c : super.getContents()) {				if (c instanceof B4element) {					B4element element = (B4element) c;					H5input input = (H5input) element.get(0);						if (value.equals(input.getAttrMap().get(H5input.Attr.value))) {						input.checked(true);							break;					}				}			}		}		return this;	}}